def read_original_records(
    rules: dict[str, Any],
) -> dict[tuple[str, str], list[dict[str, Any]]]:
    """Read actual mapped cells, ignoring incorrect worksheet dimensions."""
    mapping_groups: dict[tuple[str, str], list[dict[str, Any]]] = (
        collections.defaultdict(list)
    )
    for mapping in rules["field_mappings"]:
        file_name = mapping["source_file"]
        if file_name not in EXCEL_SOURCES:
            continue
        mapping_groups[(file_name, mapping["source_sheet"])].append(mapping)

    records: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for file_name in EXCEL_SOURCES:
        path = ROOT / file_name
        workbook = openpyxl.load_workbook(
            path,
            read_only=False,
            data_only=False,
        )
        cached_workbook = (
            openpyxl.load_workbook(path, read_only=False, data_only=True)
            if file_name == "30天复盘(9).xlsx"
            else None
        )
        for sheet_name in workbook.sheetnames:
            key = (file_name, sheet_name)
            mappings = sorted(
                mapping_groups[key],
                key=lambda item: column_name_from_position(item["source_position"]),
            )
            if not mappings:
                continue
            worksheet = workbook[sheet_name]
            cached_worksheet = (
                cached_workbook[sheet_name] if cached_workbook is not None else None
            )
            header_row = HEADER_ROWS[key]
            columns = [
                column_name_from_position(item["source_position"])
                for item in mappings
            ]
            headers = [item["source_field"] for item in mappings]
            data_rows: list[dict[str, Any]] = []
            # Stage03 established a contiguous effective region. Scan mapped columns
            # only, so false A1 dimensions and formatting inflation cannot truncate or
            # inflate the standardized record set.
            last_candidate_row = {
                ("30天复盘(9).xlsx", "30天交易复盘明细"): 132,
                ("30天复盘(9).xlsx", "资金变动记录"): 8,
                ("30天复盘(9).xlsx", "复盘说明与字段定义"): 107,
                ("Binance-交易流水-a.xlsx", "Sheet0"): 21624,
                ("Binance-合约订单历史记录-a.xlsx", "Sheet0"): 1110,
                ("Binance-合约交易历史记录-a.xlsx", "Sheet0"): 8351,
                ("Binance-合约交易流水-a.xlsx", "Sheet0"): 21462,
                ("Binance-合约仓位历史记录-a.xlsx", "Sheet0"): 146,
            }[key]
            for row_number in range(header_row + 1, last_candidate_row + 1):
                values = {
                    header: worksheet.cell(row_number, column).value
                    for header, column in zip(headers, columns)
                }
                if not any(value not in (None, "") for value in values.values()):
                    continue
                cached_values = {
                    header: (
                        cached_worksheet.cell(row_number, column).value
                        if cached_worksheet is not None
                        else values[header]
                    )
                    for header, column in zip(headers, columns)
                }
                data_rows.append(
                    {
                        "row_number": row_number,
                        "headers": headers,
                        "values": values,
                        "cached_values": cached_values,
                    }
                )
            records[key] = data_rows
        workbook.close()
        if cached_workbook is not None:
            cached_workbook.close()

