def verify_zip(req: dict, zip_path: Path, official_sha: str) -> dict:
    local_sha = sha256_file(zip_path)
    if local_sha != official_sha:
        raise FormalBlock(
            "OFFICIAL_CHECKSUM_FAILURE",
            "官方CHECKSUM与本地ZIP SHA-256不一致",
            {
                "requirement_id": req["requirement_id"],
                "official_sha256": official_sha,
                "local_sha256": local_sha,
                "zip_path": str(zip_path),
            },
        )
    with zip_path.open("rb") as f:
        magic = f.read(4)
    if magic[:2] != b"PK":
        raise FormalBlock("ZIP_MAGIC_FAILURE", "下载内容不是ZIP，可能是HTML错误页", {"zip_path": str(zip_path)})
    try:
        with zipfile.ZipFile(zip_path) as zf:
            names = zf.namelist()
            if names != [expected_inner_csv(req)]:
                raise FormalBlock(
                    "ZIP_INNER_FILENAME_MISMATCH",
                    "ZIP内部成员或文件名异常",
                    {
                        "requirement_id": req["requirement_id"],
                        "expected": [expected_inner_csv(req)],
                        "actual": names,
                    },
                )
            info = zf.getinfo(names[0])
            if info.file_size <= 0:
                raise FormalBlock("ZIP_INNER_EMPTY", "ZIP内部CSV为空", {"requirement_id": req["requirement_id"]})
            bad = zf.testzip()
            if bad is not None:
                raise FormalBlock("ZIP_CRC_FAILURE", "ZIP CRC检查失败", {"requirement_id": req["requirement_id"], "member": bad})
    except zipfile.BadZipFile as exc:
        raise FormalBlock("ZIP_STRUCTURE_FAILURE", "ZIP损坏或无法打开", {"error": str(exc), "zip_path": str(zip_path)})
    return {
        "local_zip_sha256": local_sha,
        "official_sha256": official_sha,
        "zip_member_count": 1,
        "zip_inner_filename": names[0],
        "uncompressed_csv_bytes": info.file_size,
        "zip_crc_passed": True,
        "zip_structure_passed": True,
    }

